import test from 'node:test';import assert from 'node:assert/strict';import fs from 'node:fs/promises';import os from 'node:os';import {join} from 'node:path';
import {ExecutionBudget} from '../src/budget.mjs';
const inherited={usedCalls:3,startedAt:['2026-10-15T06:29:50.550Z','2026-10-15T06:36:16.619Z','2026-10-15T06:39:01.549Z']};
test('inherited counts, single concurrency, four incremental attempts and repeated import',async()=>{const root=await fs.mkdtemp(join(os.tmpdir(),'fix1-budget-')),file=join(root,'b.sqlite');let b=new ExecutionBudget(file,inherited);try{assert.equal(b.status().total,3);const a=b.reserve();assert.throws(()=>b.reserve(),/MODEL_OWNER_BUSY/);assert.throws(()=>b.reconcile(a),/PROCESS_STILL_ACTIVE/);b.finish(a,true);for(let i=0;i<3;i++)b.finish(b.reserve(),true);assert.equal(b.status().total,7);assert.throws(()=>b.reserve(),/FIX1_MODEL_LIMIT/);b.close();b=new ExecutionBudget(file,inherited);assert.deepEqual(b.status(),{total:7,newCalls:4,active:0});assert.throws(()=>new ExecutionBudget(file,{usedCalls:0,startedAt:[]}),/RECONCILIATION/);}finally{b.close();await fs.rm(root,{recursive:true,force:true});}});
test('unconfirmed termination retains active slot and consumed attempt',async()=>{const root=await fs.mkdtemp(join(os.tmpdir(),'fix1-budget-')),b=new ExecutionBudget(join(root,'b.sqlite'),inherited);try{const id=b.reserve();b.finish(id,false);assert.deepEqual(b.status(),{total:4,newCalls:1,active:1});assert.throws(()=>b.reserve(),/MODEL_OWNER_BUSY/);}finally{b.close();await fs.rm(root,{recursive:true,force:true});}});
